(()=>{const D=window.PORTFOLIO_DATA,$=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)],E=s=>String(s||'').replace(/[&<>"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[m]));$('#favicon').href=D.brandIcon;$$('.brand-white').forEach(i=>i.src=D.brandWhite);$$('.brand-icon').forEach(i=>i.src=D.brandIcon);$('#logoStat').textContent=Math.max(77,D.logos.length+D.archive.length)+'+';const labels={technology:'Technology',fashion:'Fashion',food:'Food',corporate:'Corporate',lifestyle:'Lifestyle',entertainment:'Entertainment','real-estate':'Real Estate',energy:'Energy'};function card(x){return `<article class="logo-card reveal" tabindex="0" data-src="${x.src}" data-title="${E(x.name)}" data-type="${E(x.industry)}" data-filter="${E(x.category)}" data-tone="${E(x.tone)}"><div class="logo-frame ${x.tone==='dark'?'dark':'light'}"><img src="${x.src}" alt="${E(x.name)} logo" loading="lazy"></div><div class="info"><span>${E(labels[x.category]||x.category)}</span><h3>${E(x.name)}</h3><p>${E(x.industry)}</p></div></article>`}function arch(x){return `<article class="logo-card archive reveal" data-filter="${E(x.category)}"><div class="logo-frame light"><b>${E(x.name)}</b></div><div class="info"><span>${E(labels[x.category]||x.category)}</span><h3>${E(x.name)}</h3><p>${E(x.industry)} · archive project</p></div></article>`}$('#logoGrid').innerHTML=D.logos.map(card).join('')+D.archive.map(arch).join('');function fcard(x){return `<article class="flyer-card reveal" tabindex="0" data-src="${x.src}" data-title="${E(x.name)}" data-type="${E(x.industry)}" data-filter="${E(x.category)}" data-tone="${E(x.tone)}"><div class="flyer-frame ${x.tone==='dark'?'dark':'light'}"><img src="${x.src}" alt="${E(x.name)}" loading="lazy"></div><div class="info"><span>${E(x.industry)}</span><h3>${E(x.name)}</h3></div></article>`}$('#flyerGrid').innerHTML=D.flyers.map(fcard).join('');const rows=$$('.marquee-row');[0,1,2].forEach(n=>{let set=D.logos.filter((_,i)=>i%3===n),html=set.map(x=>`<div class="m-logo ${x.tone==='dark'?'dark':'light'}"><img src="${x.src}" alt="${E(x.name)}"><span>${E(x.name)}</span></div>`).join('');rows[n].innerHTML=`<div class="m-track">${html}${html}</div>`});function filters(btns,cards,prop){btns.forEach(b=>b.onclick=()=>{btns.forEach(x=>x.classList.remove('active'));b.classList.add('active');let v=b.dataset[prop];$$(cards).forEach(c=>c.classList.toggle('hidden',v!=='all'&&c.dataset.filter!==v))})}filters($$('.logo-filter'),'.logo-card','logoFilter');filters($$('.flyer-filter'),'.flyer-card','flyerFilter');const lb=$('#lightbox'),li=$('#lbImg'),lm=$('#lbMedia');document.addEventListener('click',e=>{let c=e.target.closest('[data-src]');if(c){li.src=c.dataset.src;$('#lbTitle').textContent=c.dataset.title;$('#lbType').textContent=c.dataset.type;lm.className='lightbox-media '+(c.dataset.tone==='dark'?'dark':'light');lb.classList.add('open');document.body.classList.add('lock')}if(e.target.matches('[data-close]')||e.target.id==='lightbox'){lb.classList.remove('open');document.body.classList.remove('lock')}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){lb.classList.remove('open');document.body.classList.remove('lock')}});new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)e.target.classList.add('visible')}),{threshold:.06}).observe(document.body);$$('.reveal').forEach(el=>setTimeout(()=>el.classList.add('visible'),60));$('#menuToggle').onclick=()=>$('#mainNav').classList.toggle('open');})();
